insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'C# / .NET', 'How do async and await improve scalability in an ASP.NET Core API?', 'They let a request release its worker thread while waiting for I/O, so the server can serve other requests. They do not make CPU-bound work faster.', 'Use await repository.GetAsync(id, cancellationToken); avoid .Result or .Wait(), which can block threads.', 'L1', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'C# / .NET', 'How do you make a checkout endpoint safe to retry?', 'Use an idempotency key, persist its outcome atomically with the operation, and return the same result for duplicate requests.', 'A unique constraint on customer ID plus key prevents a network retry from creating a second order.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'C# / .NET', 'How do you design a .NET service for cancellation and timeouts?', 'Propagate CancellationToken through async boundaries, set bounded dependency timeouts, and distinguish caller cancellation from service failure.', 'Pass HttpContext.RequestAborted to downstream calls and avoid retrying a canceled request.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'C# / .NET', 'Explain dependency injection and its lifetime choices in .NET.', 'DI supplies dependencies from outside a class. Transient creates per resolution, scoped is per request scope, and singleton is shared for the application''s lifetime.', 'Register a DbContext as scoped; do not capture it in a singleton service.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'C# / .NET', 'What is the difference between an interface and an abstract class?', 'An interface defines a contract that types can implement; an abstract class can share state and implementation while still requiring derived behavior.', 'Use an interface for a payment-provider contract and a base class only when shared implementation is meaningful.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'C# / .NET', 'How do you handle exceptions in an ASP.NET Core API?', 'Use centralized exception handling, map known failures to appropriate problem responses, log diagnostic context safely, and avoid leaking internals.', 'Return a validation problem for invalid input and a correlation ID for an unexpected server error.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'Angular', 'How do you manage shared state between Angular components?', 'Use a shared service with RxJS streams for modest state, or a state library when workflows and state transitions become complex. Keep ownership explicit.', 'A service can expose a private BehaviorSubject and a read-only observable; components subscribe with async pipe.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'Angular', 'How would you keep a large product-list page responsive?', 'Paginate or virtualize results, debounce search, cancel stale requests, lazy-load routes, and track items by stable IDs.', 'Use switchMap for typeahead so a late response for an older query cannot replace the newest results.', 'L2', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'Angular', 'What is the difference between an Observable and a Promise?', 'A Promise resolves once; an Observable can emit many values over time and supports cancellation through unsubscription and stream operators.', 'Use an Observable for form value changes and a Promise-like one-shot result for a single completion.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'Angular', 'What is the difference between a component and a service in Angular?', 'A component owns a view and its interaction; a service contains reusable logic or shared data and is injected where needed.', 'Keep HTTP access in a service and let the component bind its observable results to the template.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'Angular', 'How does Angular form validation work?', 'Validators report control errors; reactive forms make control structure and validation rules explicit in TypeScript.', 'Use Validators.required and Validators.email, then display messages only after the control is touched or submitted.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'Angular', 'How do you prevent memory leaks from Angular subscriptions?', 'Prefer async pipe for template streams or use lifecycle-aware cleanup for imperative subscriptions.', 'Use takeUntilDestroyed in supported Angular versions for component-owned subscriptions.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'Azure', 'How would you secure secrets used by an Azure-hosted application?', 'Store secrets in Key Vault, access them with managed identity, scope permissions narrowly, rotate credentials, and monitor access.', 'Enable a system-assigned identity on App Service and grant it only the required Key Vault secret-read role.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'Azure', 'How would you process order events reliably at scale?', 'Publish durable events, partition by order or customer key, make consumers idempotent, retry transient failures, and isolate poison messages.', 'A queue-triggered worker records processed event IDs and sends repeatedly failing messages to a dead-letter queue.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'Azure', 'How do you observe a distributed request across multiple services?', 'Propagate trace context and correlation IDs, emit structured logs and metrics, and create spans around dependency calls.', 'Use OpenTelemetry instrumentation and correlate traces with request and dependency error-rate dashboards.', 'L3', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'Azure', 'When would you choose App Service versus Azure Functions?', 'Use App Service for a continuously available web application or API; use Functions for event-driven or scheduled workloads with appropriate hosting and runtime controls.', 'Host a REST API on App Service and a queue-triggered image processor as a Function.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'Azure', 'What is a resource group, and how should it be used?', 'A resource group is a lifecycle and management boundary for Azure resources. Organize resources around ownership and deployment lifecycle, with RBAC and tags.', 'Keep a production app''s related resources together where shared deployment and access policy make sense.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'Azure', 'How would you design a CI/CD pipeline for an Azure application?', 'Build once, run automated tests and security checks, publish an immutable artifact, deploy through environments, and gate production with health validation and rollback.', 'Use workload identity or a service connection with least privilege rather than long-lived secrets in YAML.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'SQL', 'A query became slow as a table grew. How do you investigate?', 'Measure first, inspect the actual execution plan and waits, then address scans, bad estimates, missing or unused indexes, and excessive result size.', 'Compare logical reads before and after a targeted index; validate write overhead and parameter-sensitive plans.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'SQL', 'How do you prevent overselling when two buyers request the last item?', 'Use an atomic conditional update or transaction that checks available quantity and reserves inventory exactly once.', 'UPDATE Inventory SET Available = Available - 1 WHERE Sku = @sku AND Available > 0; check affected rows.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'SQL', 'What is the difference between a clustered and nonclustered index?', 'A clustered index defines the table''s row organization in many relational engines; a nonclustered index is a separate lookup structure that points to rows.', 'Choose keys based on access patterns and verify the query plan instead of adding indexes speculatively.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'SQL', 'How do INNER JOIN and LEFT JOIN differ?', 'INNER JOIN returns matching row pairs; LEFT JOIN preserves every left-side row and fills missing right-side columns with NULL.', 'Use LEFT JOIN to list all customers, including customers with no orders.', 'L1', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'SQL', 'What is a transaction, and why are ACID properties useful?', 'A transaction groups changes atomically; ACID describes atomicity, consistency, isolation, and durability guarantees.', 'Debit and credit account updates should commit together or roll back together.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'SQL', 'How do you choose columns for a composite index?', 'Start from query predicates, joins, ordering, and selectivity; align key order to common access patterns and validate with actual plans.', 'An index on (TenantId, CreatedAt) can support tenant-scoped date-range queries when that matches workload.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'EF Core', 'What causes the N+1 query problem, and how do you prevent it?', 'Loading a collection separately for every parent creates many round trips. Project the required shape or use a deliberate eager-loading strategy.', 'Select orders with customer names in one projection instead of looping through orders and querying each customer.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'EF Core', 'When would you use optimistic concurrency in EF Core?', 'Use it when conflicts are relatively uncommon and you want to detect, rather than silently overwrite, concurrent updates.', 'Add a row-version token and handle DbUpdateConcurrencyException with a reload, merge, or conflict response.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'EF Core', 'How do you avoid accidentally loading too much data with EF Core?', 'Project only needed columns, paginate, use AsNoTracking for read-only work, and inspect generated SQL and query plans.', 'Select new ProductSummary(p.Id, p.Name) rather than returning a full entity graph.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'EF Core', 'How do EF Core migrations fit into a deployment process?', 'Migrations version schema changes, but production deployment should review generated SQL and apply changes in a controlled, backward-compatible sequence.', 'Add a nullable column, deploy compatible application code, backfill, then enforce stricter constraints.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'EF Core', 'How do Include and projection differ for related data?', 'Include loads entity navigations; projection selects the response shape and often avoids materializing unnecessary columns or entities.', 'For an API DTO, select order ID and customer name instead of Include-ing a full customer entity.', 'L2', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'EF Core', 'What is the difference between tracking and AsNoTracking queries?', 'Tracking lets the DbContext detect changes for updates; no-tracking avoids change-tracker overhead for read-only results.', 'Use AsNoTracking on a reporting endpoint that only returns DTOs.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'LINQ', 'What is deferred execution in LINQ, and when can it surprise you?', 'Many LINQ operators build a query that runs only when enumerated. Re-enumerating can repeat work or observe changed data.', 'Call ToList() once when you need a stable in-memory snapshot.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'LINQ', 'Why can calling ToList too early hurt a data query?', 'It materializes rows before later filters or projections, increasing database transfer and application memory.', 'Apply Where and Select to IQueryable first; materialize only after the server-side query is shaped.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'LINQ', 'How do Select and SelectMany differ?', 'Select maps each item to one result; SelectMany maps each item to a sequence and flattens those sequences into one result stream.', 'orders.SelectMany(o => o.Lines) produces one sequence of all order lines.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'LINQ', 'How would you group sales by month using LINQ?', 'Project each row to a stable year/month key and aggregate with GroupBy and Sum.', 'Group by new { sale.Date.Year, sale.Date.Month } and sum sale.Amount.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'LINQ', 'What is the difference between First, FirstOrDefault, Single, and SingleOrDefault?', 'First returns the first match; Single requires exactly one. The OrDefault variants return a default when none exists, while Single still throws on multiple matches.', 'Use Single when uniqueness is a business invariant and surface a clear error if it is violated.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'LINQ', 'Why can modifying a collection while enumerating it fail?', 'The enumerator may detect collection changes and throw, and the intended iteration behavior becomes ambiguous.', 'Collect items to remove with Where(...).ToList(), then remove them in a separate pass.', 'L3', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'System Design', 'Design a highly available service that stores user preferences.', 'Define consistency and availability needs, partition by user ID, cache hot reads, replicate durable data, and make writes idempotent with observable failure handling.', 'Use an API, stateless service instances, a partitioned database, cache-aside reads, and a durable change event.', 'L1', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'System Design', 'Design a cart that supports bursts and remains available.', 'Partition cart data by user, keep writes idempotent, use a durable store, cache carefully, and define behavior for stale prices and inventory.', 'The cart stores item IDs and quantities; checkout revalidates price and stock before order placement.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'System Design', 'How would you build a globally read-heavy catalog?', 'Separate writes from reads, replicate or cache read models near users, version updates, and define freshness and fallback behavior.', 'Publish catalog changes to a stream that updates regional search indexes asynchronously.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'System Design', 'How would you structure a basic employee leave-management API?', 'Separate employee, leave request, and approval responsibilities; validate transitions; persist audit history; and notify asynchronously.', 'POST creates a pending request; an authorized approver changes its state using a versioned command.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'System Design', 'How do you design audit history for business records?', 'Record actor, timestamp, action, entity identity, and necessary before/after values with retention, access, and integrity controls.', 'Write the audit event in the same transaction as the business update or through a reliable outbox.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'System Design', 'How do you integrate with an unreliable third-party API?', 'Set deadlines, use bounded retries with backoff for safe operations, add circuit breaking and idempotency, and provide a fallback or asynchronous workflow.', 'Queue a notification for retry rather than blocking checkout on an optional email provider.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'Behavioral', 'Tell me about a time you disagreed with a technical decision.', 'Explain the shared goal, evidence you gathered, alternatives and trade-offs, how you communicated, and what you learned from the outcome.', 'Use STAR: situation, task, action, result; quantify reliability, latency, cost, or delivery impact where possible.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'Behavioral', 'Describe a time you took ownership of a customer-impacting issue.', 'Show how you limited impact, communicated clearly, drove investigation through resolution, and added prevention rather than stopping at a workaround.', 'Give a measurable result such as reduced recovery time or prevented repeat incidents.', 'L2', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'Behavioral', 'Tell me about a technically difficult problem you solved.', 'Describe constraints, competing hypotheses, how you used data to narrow the problem, the solution, and the measured outcome.', 'Mention how you validated the fix and what changed in tests, monitoring, or design afterward.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'Behavioral', 'How do you handle changing requirements during a delivery?', 'Clarify the outcome, assess scope and dependencies, communicate schedule or quality trade-offs, and keep changes visible to stakeholders.', 'Track the new acceptance criteria and agree what moves out of the current release.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'Behavioral', 'How do you explain a production defect to a nontechnical stakeholder?', 'State customer impact, current status, mitigation, next update time, and follow-up without hiding uncertainty behind jargon.', 'Separate confirmed facts from the investigation''s current hypothesis.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'Behavioral', 'How do you prioritize defects when several teams are affected?', 'Rank by customer impact, severity, scope, workarounds, and risk; coordinate owners and communicate the decision and review time.', 'Stabilize a widespread outage before addressing a cosmetic issue with a safe workaround.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'JavaScript / TypeScript', 'What is a closure, and how can it be useful in TypeScript?', 'A closure is a function together with access to its lexical scope. It is useful for encapsulating state and composing callbacks, but captured state should remain understandable.', 'A factory can keep a counter variable private and return an increment function.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'JavaScript / TypeScript', 'How do you prevent stale search results from overwriting newer results in Angular?', 'Switch to the newest request and cancel or ignore prior work. Also represent loading, empty, error, and success states explicitly.', 'Use a debounced input stream with switchMap to an HTTP observable.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'JavaScript / TypeScript', 'What is the event loop, and why does blocking work hurt a web application?', 'The event loop coordinates queued work and asynchronous callbacks. Long synchronous tasks prevent rendering and input handling until they finish.', 'Move expensive computation to a worker or split it into bounded chunks rather than blocking a UI event handler.', 'L3', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'JavaScript / TypeScript', 'Why use TypeScript interfaces or types in an Angular application?', 'They document expected data shapes and enable compile-time checking, while runtime validation is still needed for untrusted responses.', 'Type an API response as a DTO and validate critical external fields before using them.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'JavaScript / TypeScript', 'How do let, const, and var differ?', 'let and const are block-scoped; const prevents rebinding but does not freeze an object. var is function-scoped and has legacy hoisting behavior.', 'Prefer const by default and use let when reassignment is needed.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'JavaScript / TypeScript', 'When should a function return an Observable rather than subscribe internally?', 'Return the stream when the caller owns composition, error handling, and lifecycle; subscribe at an appropriate boundary such as a component or effect.', 'A data service returns HttpClient.get(); the component uses async pipe rather than a hidden subscription in the service.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'ASP.NET Core', 'Why does middleware order matter in ASP.NET Core?', 'Middleware executes in registration order on the request path and reverse order on the response path. Authentication, authorization, routing, and exception handling need deliberate placement.', 'Register authentication before authorization so authorization can use the authenticated principal.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'ASP.NET Core', 'How would you implement request validation consistently in a .NET API?', 'Validate at the boundary, return a stable client-error contract, keep business invariants in the domain/service layer, and avoid duplicating rules across controllers.', 'Reject malformed quantity at request validation, then enforce available inventory during the transactional operation.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'ASP.NET Core', 'How do you prevent thread-pool starvation in a .NET web service?', 'Use asynchronous I/O end-to-end, avoid blocking waits, bound concurrency, and profile thread-pool and dependency behavior under load.', 'Replace synchronous database calls and .Result with awaited async APIs.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'ASP.NET Core', 'How do you structure an ASP.NET Core application for maintainability?', 'Keep transport concerns in controllers/endpoints, business rules in application/domain services, persistence behind appropriate abstractions, and configuration externalized.', 'A controller validates and delegates a command rather than embedding pricing and authorization rules.', 'L1', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'ASP.NET Core', 'How do you handle configuration for development, test, and production?', 'Use environment-specific configuration and secure secret providers, validate required options at startup, and avoid committing credentials.', 'Bind a typed options class and fail startup clearly if a required endpoint is missing.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'ASP.NET Core', 'How can an ASP.NET Core API support consistent request tracing?', 'Use structured logs, distributed tracing context, and a correlation/trace ID propagated across downstream calls without logging sensitive payloads.', 'Include trace ID and operation name in error logs so a support team can locate the corresponding trace.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'REST APIs', 'How do you evolve a public API without breaking existing clients?', 'Prefer additive changes, document contracts, measure client usage, deprecate with notice, and introduce a new version only for incompatible changes.', 'Add an optional response property; version a changed meaning or required request field.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'REST APIs', 'What should an API return when an asynchronous order is still processing?', 'Return a clear accepted/in-progress representation with a stable operation or resource ID, documented status retrieval, and safe retry semantics.', 'Return 202 with an order-status URI; clients poll or subscribe until the order reaches a terminal state.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'REST APIs', 'How should pagination work for a rapidly changing large dataset?', 'Prefer stable cursor/keyset pagination when offset scans become expensive or rows shift. Define ordering and cursor semantics explicitly.', 'Continue after the last seen (CreatedAt, Id) pair using a deterministic sort.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'REST APIs', 'How do you choose appropriate HTTP status codes for a CRUD API?', 'Use status codes consistently for success, client errors, authentication/authorization, missing resources, conflicts, and server failures.', 'Return 201 with a Location for creation, 404 for an absent resource, and 409 for a conflicting state.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'REST APIs', 'What is the purpose of model validation in a web API?', 'It rejects malformed or incomplete input at the boundary with useful client feedback before business processing.', 'Validate required fields and numeric ranges, but still enforce domain invariants in the service.', 'L2', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'REST APIs', 'How do you make an API error response useful without exposing internals?', 'Return a stable problem-details shape with a safe message, validation fields where applicable, and a correlation identifier; log diagnostic details privately.', 'A 500 response says the request could not be completed and includes a trace ID, not a stack trace or SQL text.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'Testing', 'What belongs in unit, integration, and end-to-end tests?', 'Unit tests isolate logic, integration tests verify component boundaries such as databases, and end-to-end tests exercise a critical user flow. Balance confidence with execution cost.', 'Test a pricing rule as a unit, repository mappings with a real test database, and checkout as a small set of UI flows.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'Testing', 'How would you test a payment workflow without charging a real card?', 'Use provider test credentials or a contract-faithful fake, cover success, decline, timeout, and ambiguous outcomes, and verify idempotency and compensation.', 'Simulate a timeout after the provider accepted payment, then ensure retry uses the same payment idempotency key.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'Testing', 'What is the purpose of property-based testing?', 'It checks general properties across many generated inputs, which can expose edge cases missed by hand-picked examples.', 'For any list, sorting should preserve its multiset and produce a nondecreasing sequence.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'Testing', 'How do you test a service that depends on a database?', 'Unit-test business decisions with focused substitutes where useful, and integration-test database behavior against the actual provider or a faithful disposable instance.', 'Use a real SQL test database for transaction and query translation tests instead of assuming an in-memory provider behaves identically.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'Testing', 'What makes a unit test reliable and maintainable?', 'It is deterministic, focused on observable behavior, isolated from unrelated external systems, and produces useful failure messages.', 'Use fixed test inputs and assert a returned result instead of sleeping while waiting for timing.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'Testing', 'How do you choose what to automate in a regression suite?', 'Prioritize frequent, high-impact, deterministic workflows and business rules; keep a smaller number of end-to-end checks and test lower layers more extensively.', 'Automate payment totals and permissions as fast tests, with a few full checkout journeys.', 'L3', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'Data Structures & Algorithms', 'How would you find the first non-repeating character in a string?', 'Count characters in one pass, then scan again and return the first whose frequency is one. This is linear in string length.', 'For “swiss”, counts are s:3, w:1, i:1; the first unique character is w.', 'L1', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'Data Structures & Algorithms', 'How would you return the top K most frequent product IDs?', 'Count frequencies, then use a size-K min-heap for O(n log k) time or sort all distinct items when that is simpler and acceptable.', 'For counts {A:5, B:2, C:7}, K=2 returns C and A.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'Data Structures & Algorithms', 'How do you detect a cycle in a linked list with constant extra space?', 'Use slow and fast pointers. If they meet, a cycle exists; if the fast pointer reaches null, there is no cycle.', 'Advance slow by one link and fast by two links until they meet or fast reaches the end.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'Data Structures & Algorithms', 'How can you check whether two strings are anagrams?', 'Normalize according to the requirement, then compare character counts; this is linear time for a bounded alphabet or hash-map-based input.', 'For case-insensitive comparison, normalize case first and count each character in both strings.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'Data Structures & Algorithms', 'How would you find duplicates in an integer array?', 'Use a hash set for expected O(n) time and O(n) extra space, or sort first when mutation is allowed and O(n log n) time is acceptable.', 'As each number is visited, a failed Add to the set signals a repeated value.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'Data Structures & Algorithms', 'How would you merge two sorted arrays?', 'Use two pointers, repeatedly take the smaller current value, and append remaining items; time is O(m+n).', 'Compare the heads of [1,4,8] and [2,3,9] and emit [1,2,3,4,8,9].', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'DevOps', 'What makes a deployment strategy safe for a critical service?', 'Use immutable artifacts, staged rollout, health gates, observability, a tested rollback path, and backward-compatible schema changes.', 'Canary a small percentage, compare error and latency metrics, then increase traffic only when healthy.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'DevOps', 'How do you roll out a database schema change with no planned downtime?', 'Use an expand-and-contract sequence: add compatible schema, deploy code that supports both shapes, backfill, switch reads/writes, then remove obsolete schema later.', 'Add a nullable replacement column, dual-write and backfill, then make it required after all app versions migrate.', 'L2', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'DevOps', 'How would you decide whether a service is healthy enough to receive traffic?', 'Use readiness signals tied to ability to serve, liveness only for unrecoverable process failure, and rollout gates based on user-facing metrics.', 'A process can be alive while its critical dependency is unavailable, so readiness should reflect actual serving capability.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'DevOps', 'What should a CI pipeline do before creating a deployable artifact?', 'Restore reproducibly, compile, run relevant tests and static/security checks, then package a versioned artifact with traceable build metadata.', 'Promote the same tested artifact between environments instead of rebuilding different bits for production.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'DevOps', 'Why should application configuration be external to a build artifact?', 'The same artifact can then be promoted across environments while environment-specific endpoints and secrets are managed separately.', 'Inject a production connection string from a secret store at deployment/runtime rather than compiling it into the app.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'DevOps', 'What is the difference between continuous delivery and continuous deployment?', 'Continuous delivery keeps changes releasable but may require a human production approval; continuous deployment automatically releases every change that passes its gates.', 'A regulated production environment can use automated tests plus a manual approval before release.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'Identity & Security', 'How do authentication and authorization differ?', 'Authentication establishes who the caller is; authorization determines what that identity may do. Enforce authorization on the server for every protected operation.', 'A valid token identifies a user, while a role or policy check decides whether that user can approve a request.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'Identity & Security', 'How do you protect an API from unauthorized object-level access?', 'Authorize access to the requested resource using the caller''s identity and policy, not merely a valid login or a client-supplied object ID.', 'Load the order constrained by both order ID and the caller''s account/tenant scope.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'Identity & Security', 'Why should secrets not be placed in source code or build logs?', 'They can persist in repository history, artifacts, logs, and caches. Use a secret manager, scoped identities, redaction, and rotation if exposed.', 'A CI job retrieves a short-lived credential at runtime from a managed secret store.', 'L3', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'Identity & Security', 'What is the principle of least privilege?', 'Give users and services only the permissions they need, at the narrowest scope and duration, and review them regularly.', 'A read-only reporting identity should not be able to update production business records.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'Identity & Security', 'How should a web application store user passwords?', 'Avoid storing plaintext or reversible passwords; use a proven identity provider or modern salted password hashing with appropriate work factors and protections.', 'Use ASP.NET Core Identity or a managed identity service instead of inventing a password scheme.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'Identity & Security', 'What is the difference between OAuth 2.0 and OpenID Connect?', 'OAuth 2.0 is an authorization framework for delegated access; OpenID Connect adds an identity layer for authenticating users.', 'Use OIDC login to establish user identity and OAuth access tokens to authorize API calls.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Microsoft', 'Microservices', 'How does the outbox pattern help publish reliable domain events?', 'Write the business change and an event record in the same database transaction, then publish the outbox asynchronously with idempotent consumers.', 'An order transaction stores the order and OrderCreated row; a worker publishes and marks the event delivered.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Amazon', 'Microservices', 'How do you handle a checkout that spans order, inventory, and payment services?', 'Use a saga with explicit states, idempotent commands, timeouts, compensating actions, and reconciliation for ambiguous external outcomes.', 'Reserve stock, authorize payment, confirm the order; release inventory if payment is definitively declined.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Google', 'Microservices', 'When is a modular monolith a better choice than microservices?', 'When domain boundaries or independent scaling/ownership do not justify distributed-system costs, a modular monolith can preserve clear boundaries with simpler operations.', 'Separate catalog and pricing modules behind interfaces in one deployable until real team or scale needs warrant extraction.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Infosys', 'Microservices', 'How do you decide whether a feature belongs in a separate service?', 'Look for a cohesive business capability, clear ownership and data boundaries, independent scaling or deployment needs, and a justified operational cost.', 'Do not split a small CRUD module solely because separate services are fashionable.', 'L1', false) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('TCS', 'Microservices', 'Why should each service own its data boundary?', 'Independent ownership reduces coupling and lets a service enforce its invariants, while cross-service reads use contracts or purpose-built read models.', 'Expose an Order API rather than letting another service update the order database tables directly.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
insert into public.questions (company, topic, question, answer, example, access_level, is_free) values ('Accenture', 'Microservices', 'How do you maintain consistency when services own separate databases?', 'Use local transactions within each service, publish reliable events, design consumers to be idempotent, and model cross-service workflows as eventual consistency or sagas.', 'An order service commits an order and outbox event, then inventory consumes it and reports its reservation result.', null, true) on conflict (company, topic, question) do update set answer = excluded.answer, example = excluded.example, access_level = excluded.access_level, is_free = excluded.is_free;
