-- Seed the company interview question bank. Run after schema.sql.

-- The first ten questions in each topic are public previews; later additions require Pro.
with ranked_questions as (
  select id, row_number() over (partition by topic order by company asc, id asc) as topic_position
  from public.questions
)
update public.questions as question
set is_free = ranked_questions.topic_position <= 10
from ranked_questions
where question.id = ranked_questions.id;
